ByteVector extractSubrange(uint index, uint length) {
    if (index >= this->size()) {
        return ByteVector();
    }

    uint endIdx = std::min(index + length, static_cast<uint>(this->size()));
    ByteVector result;
    result.insert(result.begin(), this->begin() + index, this->begin() + endIdx);
    return result;
}

