ByteVector extractSubrangeFromByteVector(uint index, uint length) {
    if (index >= byteVector.size()) {
        return ByteVector();
    }

    uint end = index + length;
    if (end > byteVector.size()) {
        end = byteVector.size();
    }

    ByteVector subVector;
    for (uint i = index; i < end; ++i) {
        subVector.push_back(byteVector[i]);
    }

    return subVector;
}
